-- GENERATED by tools/make_tools.py from src/FSUtility.lua and firesystem/FireSystem<Module>.lua.
-- Don't edit this file: edit those, then run `python3 tools/make_tools.py`.
--[[
  FSUtility.lua  -  "FS Utility": looks after the other FS tools in the show
  ------------------------------------------------------------------------
  Run it (click it in the Plugins pool) and pick one of:

  - Reimport: imports every FS tool (FS*.xml, and FireSystem.xml if it's there) again, from the
    console's own plugins folder (gma3_library/datapools/plugins) or from a USB stick (its
    grandMA3/gma3_library/datapools/plugins folder, as MA exports it, or a plugins folder / the
    stick's top level). A tool that's already in the Plugins pool is imported over its own slot,
    a new one goes in the first free slot. FS Utility doesn't reimport itself while it runs.
  - Run all again: runs the ticked tools in build order (FS Presets first, FS Icons last). Each one
    opens its own dialog with the settings it used last time.
  - Delete all: deletes what the ticked tools made: every Layout, Macro, Sequence, MAtricks,
    Preset and Appearance whose name starts with that tool's tag ("FS CP ", "FS BS ", ...), and FS
    Icons' own images (Image 3.3101+). FS Presets' presets and FireSystem's round icons and images
    have the same names as the main FireSystem plugin's: they're only offered when FireSystem
    isn't in the Plugins pool. Nothing else is touched. It asks before deleting.

  ONE FILE, NO OTHER PLUGIN NEEDED: plugins/FSUtility.lua is generated by tools/make_tools.py
  from this source (it needs none of the FireSystem modules).
--]]

local TITLE = "FS Utility"
local SELF = "FS Utility"

-- the tools, in build order: {pool name, file, name tag (nil = names nothing of its own)}
local TOOLS = {
  {"FS Presets",         "FSPresets.xml"},
  {"FS Colour Picker",   "FSColourPicker.xml",   "CP"},
  {"FS Position Picker", "FSPositionPicker.xml", "PP"},
  {"FS Dimmer FX",       "FSDimmerFX.xml",       "DF"},
  {"FS Colour FX",       "FSColourFX.xml",       "CF"},
  {"FS Gobo & Beam",     "FSGoboBeam.xml",       "GB"},
  {"FS Bumps",           "FSBumps.xml",          "BS"},
  {"FS LOS",             "FSLOS.xml",            "LO"},
  {"FS Masters",         "FSMasters.xml"},
  {"FS Icons",           "FSIcons.xml",          "IC"},
}
local MAIN = {"FireSystem", "FireSystem.xml"}   -- the main plugin (reimported too when it's there)
local ICON_IMAGES = 3101                         -- FS Icons' own images: Image 3.3101+
local PRESET_POOLS = {1, 2, 3, 4, 5, 6, 21}

local function say(msg)
  Printf(msg)
  pcall(MessageBox, {title = TITLE, message = msg, commands = {{value = 1, name = "OK"}}})
end

local function ok(r)
  if r == nil or r == true then return true end
  return type(r) == "string" and r:lower():sub(1, 2) == "ok"
end

local function sep()
  local s
  pcall(function() s = GetPathSeparator() end)
  return (type(s) == "string" and s ~= "") and s or "/"
end

local function join(...)
  local t = {}
  for _, p in ipairs({...}) do if p and p ~= "" then t[#t + 1] = (tostring(p):gsub("[/\\]+$", "")) end end
  return table.concat(t, sep())
end

local function libraryPath()
  local dir
  pcall(function() dir = GetPath(Enums.PathType.Library) end)
  if type(dir) ~= "string" or dir == "" then pcall(function() dir = GetPath("library") end) end
  if type(dir) ~= "string" or dir == "" then return nil end
  return (dir:gsub("[/\\]+$", ""))
end

-- ==== the Plugins pool and the other pools ====

-- every object in a pool: {no, name}
local function children(pool)
  local t = {}
  pcall(function()
    for _, h in ipairs(pool:Children()) do
      local no, name = tonumber(h.no or h.No), h.name or h.Name
      if no then t[#t + 1] = {no = no, name = tostring(name or "")} end
    end
  end)
  return t
end

local POOLS = {   -- {address word, how to reach the pool}
  {"Layout",     function() return DataPool().Layouts end},
  {"Macro",      function() return DataPool().Macros end},
  {"Sequence",   function() return DataPool().Sequences end},
  {"MAtricks",   function() return DataPool().MAtricks end},
  {"Appearance", function() return ShowData().Appearances end},
}

local function plugins()
  local ok2, pool = pcall(function() return DataPool().Plugins end)
  return ok2 and pool and children(pool) or {}
end

local function pluginNamed(name)
  for _, p in ipairs(plugins()) do if p.name == name then return p.no end end
end

local function freePlugin(taken)
  local used = {}
  for _, p in ipairs(plugins()) do used[p.no] = true end
  for n = 1, 9999 do if not used[n] and not taken[n] then return n end end
end

-- ==== reimport ====

local function readable(path)
  local f = io.open(path, "r")
  if f then f:close() return true end
  return false
end

-- the plugin files in dir: ours (FS*.xml + FireSystem.xml)
local function pluginFiles(dir)
  local found, seen = {}, {}
  local function add(f) if not seen[f] then seen[f] = true found[#found + 1] = f end end
  pcall(function()
    for _, e in ipairs(DirList(dir, "*.xml") or {}) do
      local f = type(e) == "table" and (e.name or e.Name) or e
      if type(f) == "string" and (f:match("^FS%w+%.xml$") or f == MAIN[2]) then add(f) end
    end
  end)
  if #found == 0 then   -- (no DirList: look for the files we know)
    for _, t in ipairs(TOOLS) do if readable(join(dir, t[2])) then add(t[2]) end end
    if readable(join(dir, MAIN[2])) then add(MAIN[2]) end
    if readable(join(dir, "FSUtility.xml")) then add("FSUtility.xml") end
  end
  table.sort(found)
  return found
end

-- the plugin's pool name, from its XML (<Plugin Name="FS Bumps" ...>), else from the list
local function xmlName(dir, file)
  local f = io.open(join(dir, file), "r")
  if f then
    local text = f:read("*a") or ""
    f:close()
    local n = text:match('<Plugin[^>]-%sName="([^"]+)"')
    if n then return n end
  end
  for _, t in ipairs(TOOLS) do if t[2] == file then return t[1] end end
  if file == MAIN[2] then return MAIN[1] end
  if file == "FSUtility.xml" then return SELF end
  return (file:gsub("%.xml$", ""))
end

-- the folders a USB stick can hold the plugins in
local function usbDirs()
  local dirs = {}
  local drives = {}
  pcall(function() drives = Root().Temp.DriveCollect:Children() end)
  for i, d in ipairs(drives or {}) do
    if i > 1 then   -- (drive 1 is the console's own)
      local roots = {}
      pcall(function() local p = d.path or d.Path if type(p) == "string" and p ~= "" then roots[#roots + 1] = p end end)
      local name
      pcall(function() name = d.name or d.Name end)
      if type(name) == "string" and name ~= "" then
        roots[#roots + 1] = "/Volumes/" .. name   -- (onPC on a Mac)
        roots[#roots + 1] = "/media/" .. name     -- (console)
      end
      for _, r in ipairs(roots) do
        dirs[#dirs + 1] = join(r, "grandMA3", "gma3_library", "datapools", "plugins")
        dirs[#dirs + 1] = join(r, "gma3_library", "datapools", "plugins")
        dirs[#dirs + 1] = join(r, "plugins")
        dirs[#dirs + 1] = r
      end
    end
  end
  return dirs
end

local function consoleDirs()
  local lib = libraryPath()
  return lib and {join(lib, "datapools", "plugins")} or {}
end

local function reimport(fromUsb)
  local dirs = fromUsb and usbDirs() or consoleDirs()
  local dir, files
  for _, d in ipairs(dirs) do
    local f = pluginFiles(d)
    if #f > 0 then dir, files = d, f break end
  end
  if not dir then
    return say(fromUsb and "No FS plugins found on a USB stick.\nPut the plugin files (FS*.xml and FS*.lua) in grandMA3/gma3_library/datapools/plugins on the stick, plug it in and try again."
                        or "No FS plugins found in the console's plugins folder (gma3_library/datapools/plugins).")
  end
  local done, failed, skipped, taken = {}, {}, false, {}
  for _, file in ipairs(files) do
    local name = xmlName(dir, file)
    if name == SELF then
      skipped = true
    else
      local no = pluginNamed(name) or freePlugin(taken)
      taken[no] = true
      local good = false
      for _, c in ipairs({string.format('Import Plugin %d /File "%s" /Path "%s" /NoConfirm', no, file, dir),
                          string.format('Import Plugin %d /File "%s" /Path "%s"', no, file, dir)}) do
        if ok(Cmd(c)) then good = true break end
      end
      if good then done[#done + 1] = string.format("%s (Plugin %d)", name, no) else failed[#failed + 1] = name end
    end
  end
  local lines = {string.format("Reimported %d plugin(s) from %s:", #done, dir)}
  for _, d in ipairs(done) do lines[#lines + 1] = "  " .. d end
  if #failed > 0 then lines[#lines + 1] = "Couldn't import: " .. table.concat(failed, ", ") end
  if skipped then lines[#lines + 1] = "FS Utility itself was left as it is (reimport it from the Plugins pool)." end
  say(table.concat(lines, "\n"))
end

-- ==== run all again ====

local function runAll()
  local here, states = {}, {}
  for _, t in ipairs(TOOLS) do
    if pluginNamed(t[1]) then
      here[#here + 1] = t[1]
      states[#states + 1] = {name = t[1], state = true}
    end
  end
  if #here == 0 then return say("None of the FS tools are in the Plugins pool yet. Use Reimport first.") end
  local r = MessageBox({
    title = TITLE,
    message = "Runs the ticked tools in this order. Each one opens its own dialog with the settings\n" ..
              "it used last time: press its Build / OK to go on.",
    commands = {{value = 1, name = "Run"}, {value = 0, name = "Cancel"}},
    states = states,
  })
  if not r or r.result ~= 1 then return end
  local ran = {}
  for _, name in ipairs(here) do
    local on = r.states and r.states[name]
    if on == nil or on then
      Cmd(string.format('Plugin "%s"', name))
      ran[#ran + 1] = name
    end
  end
  Printf(TITLE .. ": ran " .. table.concat(ran, ", "))
end

-- ==== delete all ====

local SHARED = "FS Presets' presets and FireSystem's icons"

-- what deleting the ticked tools would remove: {address, name}
local function toDelete(tags, shared)
  local list = {}
  local function mine(name)
    for _, tag in ipairs(tags) do
      if name:sub(1, #tag + 4) == "FS " .. tag .. " " then return true end
      if tag == "IC" and name:sub(1, 6) == "FS ic " then return true end
    end
    return false
  end
  for _, p in ipairs(POOLS) do
    local ok2, pool = pcall(p[2])
    if ok2 and pool then
      for _, o in ipairs(children(pool)) do
        local m = mine(o.name) or (shared and p[1] == "Appearance" and o.name:sub(1, 5) == "FS r ")
        if m then list[#list + 1] = {string.format("%s %d", p[1], o.no), o.name} end
      end
    end
  end
  for _, pp in ipairs(PRESET_POOLS) do
    local ok2, pool = pcall(function() return DataPool().PresetPools[pp] end)
    if ok2 and pool then
      for _, o in ipairs(children(pool)) do
        if mine(o.name) or (shared and o.name:sub(1, 3) == "FS ") then
          list[#list + 1] = {string.format("Preset %d.%d", pp, o.no), o.name}
        end
      end
    end
  end
  local icons, ok3 = false, false
  for _, tag in ipairs(tags) do if tag == "IC" then icons = true end end
  if icons or shared then
    local pool
    ok3, pool = pcall(function() return ShowData().MediaPools.Images end)
    if ok3 and pool then
      for _, o in ipairs(children(pool)) do
        if (icons and o.no >= ICON_IMAGES) or (shared and o.no < ICON_IMAGES and o.name:sub(1, 3) == "fs_") then
          list[#list + 1] = {string.format("Image 3.%d", o.no), o.name}
        end
      end
    end
  end
  return list
end

local function deleteAll()
  local states = {}
  for _, t in ipairs(TOOLS) do
    if t[3] then states[#states + 1] = {name = t[1], state = true} end
  end
  local mainHere = pluginNamed(MAIN[1]) ~= nil
  if not mainHere then states[#states + 1] = {name = SHARED, state = true} end
  local r = MessageBox({
    title = TITLE,
    message = "Deletes everything the ticked tools made (layouts, macros, sequences, MAtricks, presets,\n" ..
              "appearances, FS Icons' images): only objects named with the tool's own tag.\n" ..
              (mainHere and "FireSystem is in this show, so FS Presets' presets and FireSystem's icons are kept.\n" or "") ..
              "This can't be undone (Oops still works right after).",
    commands = {{value = 1, name = "Delete"}, {value = 0, name = "Cancel"}},
    states = states,
  })
  if not r or r.result ~= 1 then return end
  local tags, shared = {}, false
  for _, t in ipairs(TOOLS) do
    local on = r.states and r.states[t[1]]
    if t[3] and (on == nil or on) then tags[#tags + 1] = t[3] end
  end
  if not mainHere then
    local on = r.states and r.states[SHARED]
    shared = on == nil or on
  end
  local list = toDelete(tags, shared)
  if #list == 0 then return say("Nothing to delete: the ticked tools haven't made anything in this show.") end
  Cmd("ClearAll")
  local failed = 0
  for _, o in ipairs(list) do
    if not ok(Cmd(string.format("Delete %s /NC", o[1]))) then failed = failed + 1 end
  end
  say(string.format("Deleted %d object(s).%s", #list - failed,
    failed > 0 and string.format(" %d couldn't be deleted (see the command line feedback).", failed) or ""))
end

-- ==== the main dialog ====

local function main(displayHandle, argument)
  local arg = tostring(argument or ""):lower()
  local pick
  if arg == "reimport" or arg == "console" then pick = 1
  elseif arg == "usb" then pick = 2
  elseif arg == "run" or arg == "rerun" then pick = 3
  elseif arg == "delete" then pick = 4
  else
    local r = MessageBox({
      title = TITLE,
      message = "Reimport: imports every FS plugin again (over its own slot in the Plugins pool).\n" ..
                "Run all again: runs the FS tools in build order, each with its last settings.\n" ..
                "Delete all: deletes everything the FS tools made in this show (asks first).",
      commands = {{value = 1, name = "Reimport from console"}, {value = 2, name = "Reimport from USB"},
                  {value = 3, name = "Run all again"}, {value = 4, name = "Delete all"}, {value = 0, name = "Cancel"}},
    })
    pick = r and r.result
  end
  if pick == 1 then reimport(false)
  elseif pick == 2 then reimport(true)
  elseif pick == 3 then runAll()
  elseif pick == 4 then deleteAll() end
end

return main
